// Three-way conflict merge of two diverged databases against a common base.
// Spec: docs/database-conflict-merge-plan.md §3. Reference: DatabaseMerger.java.
//
// Pure function over decrypted data: no I/O, no cryptography.

import { AccountInformation } from '../format/account';
import { DatabaseOptions } from '../format/options';
import { PasswordDatabase } from '../format/passwordDatabase';

/** Suffix appended to a conflicting remote account. */
export const REMOTE_SUFFIX = ' (remote)';

/** The outcome of a {@link merge} call. */
export interface MergeResult {
  /** The merged, file-less database (revision = max(local, remote) + 1). */
  merged: PasswordDatabase;
  /**
   * True when the merged result differs from the remote database and must
   * therefore be uploaded. False means the remote already holds everything
   * (only the remote changed, or both sides already agree).
   */
  uploadRequired: boolean;
  /** Number of accounts in the merged database. */
  accountCount: number;
  /** Number of conflicts preserved as `(remote)` copies. */
  conflictCount: number;
}

/**
 * Merge `local` and `remote` against their common `base` (which may be `null`,
 * treated as empty). Neither side's edits are silently lost: a genuine conflict
 * keeps the local account under its original name and preserves the remote
 * account as a copy named `"<name> (remote)"`.
 */
export function merge(
  base: PasswordDatabase | null,
  local: PasswordDatabase,
  remote: PasswordDatabase,
): MergeResult {
  const b = toMap(base);
  const l = toMap(local);
  const r = toMap(remote);

  // The merged database reuses the local encryption context so the file keeps
  // the local salt and stays decryptable with the same password, and always
  // takes DatabaseOptions from the local database.
  const merged = local.createEmptyCopy(copyOf(local.getDbOptions()));

  let conflicts = 0;

  // Names already in use by any of the three inputs, so a "(remote)" copy never
  // collides with an existing account regardless of processing order.
  const reservedNames = new Set<string>([...b.keys(), ...l.keys(), ...r.keys()]);
  const names = new Set<string>(reservedNames);

  for (const name of names) {
    const bi = b.get(name);
    const li = l.get(name);
    const ri = r.get(name);

    if (bi === undefined) {
      if (li !== undefined && ri !== undefined) {
        if (li.equals(ri)) {
          merged.addAccount(li); // both added identically
        } else {
          merged.addAccount(li); // both added differently -> conflict
          merged.addAccount(renamedCopy(ri, reservedNames));
          conflicts++;
        }
      } else if (li !== undefined) {
        merged.addAccount(li); // added locally
      } else if (ri !== undefined) {
        merged.addAccount(ri); // added remotely
      }
    } else if (li !== undefined && ri !== undefined) {
      if (li.equals(ri)) {
        merged.addAccount(li); // unchanged / converged
      } else if (li.equals(bi)) {
        merged.addAccount(ri); // remote edited only
      } else if (ri.equals(bi)) {
        merged.addAccount(li); // local edited only
      } else {
        merged.addAccount(li); // both edited -> conflict
        merged.addAccount(renamedCopy(ri, reservedNames));
        conflicts++;
      }
    } else if (li !== undefined) {
      // Present in base and local, gone from remote.
      if (!li.equals(bi)) {
        merged.addAccount(li); // delete vs edit -> keep the edit
      }
      // else: deleted remotely, nothing to add.
    } else if (ri !== undefined) {
      // Present in base and remote, gone from local.
      if (!ri.equals(bi)) {
        merged.addAccount(ri); // delete vs edit -> keep the edit
      }
      // else: deleted locally, nothing to add.
    }
    // else: deleted on both sides -> drop.
  }

  const newRevision = Math.max(local.getRevision(), remote.getRevision()) + 1;
  merged.setRevision(newRevision);

  return {
    merged,
    uploadRequired: !accountsEqual(merged, remote),
    accountCount: merged.getAccounts().length,
    conflictCount: conflicts,
  };
}

/**
 * Copy `source` under a fresh name `"<name> (remote)"`, appending a number when
 * that name is taken (e.g. `"<name> (remote 2)"`). The chosen name is added to
 * `reservedNames` so later copies don't reuse it.
 */
function renamedCopy(
  source: AccountInformation,
  reservedNames: Set<string>,
): AccountInformation {
  let name = `${source.accountName}${REMOTE_SUFFIX}`;
  let n = 1;
  while (reservedNames.has(name)) {
    n++;
    name = `${source.accountName} (remote ${n})`;
  }
  reservedNames.add(name);
  return new AccountInformation(
    name,
    source.userId,
    source.password,
    source.url,
    source.notes,
  );
}

/** Map a database's accounts by name (a `null` database yields an empty map). */
function toMap(db: PasswordDatabase | null): Map<string, AccountInformation> {
  const map = new Map<string, AccountInformation>();
  if (db) {
    for (const account of db.getAccounts()) {
      map.set(account.accountName, account);
    }
  }
  return map;
}

/** A copy of `options` (so the merged database doesn't share mutable state). */
function copyOf(options: DatabaseOptions): DatabaseOptions {
  return new DatabaseOptions(options.remoteLocation, options.authDBEntry);
}

/**
 * True when two databases hold exactly the same accounts (name + all five
 * fields), ignoring `DatabaseOptions`. Used to tell "up to date" apart from
 * "only the remote changed".
 */
export function accountsEqual(a: PasswordDatabase, b: PasswordDatabase): boolean {
  const accounts = a.getAccounts();
  if (accounts.length !== b.getAccounts().length) {
    return false;
  }
  for (const account of accounts) {
    const other = b.getAccount(account.accountName);
    if (!other || !account.equals(other)) {
      return false;
    }
  }
  return true;
}
